(function(){window.Serpent=function(cv,cfg){var ctx=cv.getContext('2d'),img=new Image(),rm=matchMedia('(prefers-reduced-motion:reduce)').matches;var dpr=Math.min(2,window.devicePixelRatio||1),W=0,H=0,ds=1,A=cfg.amp||20,boost=0,t0=performance.now(),run=false,raf=0,last=scrollY,vis=false;var STRIP=6;function size(){var r=cv.parentNode.getBoundingClientRect();W=Math.round(r.width);ds=dpr>1?.5:.6;A=(cfg.amp||20)*(W<640?.8:1);H=Math.round(img.height*ds+A*2*2.7);cv.style.height=H+'px';cv.width=W*dpr;cv.height=H*dpr;}
function draw(now){var t=(now-t0)/1000,bw=img.width*ds,off=rm?0:t*(cfg.speed||26),amp=A*(1+boost)*(rm?0:1),lam=W/1.6;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.clearRect(0,0,W,H);var ih=img.height,base=(H-ih*ds)/2;for(var x=0;x<W;x+=STRIP){var sx=((x+off)%bw+bw)%bw/ds,sw=STRIP/ds;var dy=Math.sin(x/lam*6.2832-t*.95)*amp+Math.sin(x/lam*3.1416+t*.5)*amp*.35;if(sx+sw<=img.width)ctx.drawImage(img,sx,0,sw,ih,x,base+dy,STRIP+.6,ih*ds);else{var a=img.width-sx;ctx.drawImage(img,sx,0,a,ih,x,base+dy,a*ds,ih*ds);ctx.drawImage(img,0,0,sw-a,ih,x+a*ds,base+dy,(sw-a)*ds+.6,ih*ds);}}
if(!rm){var fx=((t*160)%(W+600))-300,g=ctx.createLinearGradient(fx-110,0,fx+110,0);g.addColorStop(0,'rgba(242,241,237,0)');g.addColorStop(.5,'rgba(242,241,237,.9)');g.addColorStop(1,'rgba(242,241,237,0)');ctx.globalCompositeOperation='source-atop';ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.globalCompositeOperation='source-over';}
var dv=Math.abs(scrollY-last);last=scrollY;boost=Math.max(boost*.94,Math.min(1.6,dv/40));if(boost<.01)boost=0;}
function loop(now){if(!vis){run=false;return;}draw(now);raf=requestAnimationFrame(loop);}
var api={kick:function(v){boost=Math.max(boost,v||1.4);if(rm)draw(performance.now());}};cv.addEventListener('pointerenter',function(){api.kick(1.5);});cv.addEventListener('pointerdown',function(){api.kick(1.8);});img.onload=function(){size();cv.parentNode.classList.add('ok');draw(performance.now());if(!rm&&'IntersectionObserver'in window)new IntersectionObserver(function(e){vis=e[0].isIntersecting;if(vis&&!run){run=true;raf=requestAnimationFrame(loop);}},{rootMargin:'100px'}).observe(cv);addEventListener('resize',function(){size();draw(performance.now());});};img.src=cfg.src;return api;};})();